import {pick,simulate} from './engine.js';
import {language} from '../i18n.js';
import {escapeHTML as e} from '../explorer-views.js';
import {scenarioChart} from './release.js';
const L=(en,zh,ms)=>pick([en,zh,ms],language),P=x=>pick(x,language);
const list=items=>items.map(x=>e(P(x.label))).join(' · ');
const titles={awareness:['Understanding AI','AI 理解与认知','Memahami AI'],usage:['Everyday use','AI 日常使用','Penggunaan harian'],verification:['Output checking','AI 输出核验','Semakan hasil'],workflow:['Workflow collaboration','AI 工作流协作','Kerjasama aliran kerja'],development:['Building & automation','AI 开发与自动化','Pembangunan & automasi']};
export function renderPersonal(a,{evidence,methodology,button,summary}){
 const p=a.personal,r=a.roles[0];
 return `<div class="an-view an-profile" data-rebuild="profile">${summary(a)}<section class="personal-decision"><div><span class="an-eyebrow">${L('YOUR FIRST PRIORITY','你的首要关注','KEUTAMAAN PERTAMA ANDA')}</span><h2>${e(p.primary?P(p.primary.label):P(p.preference))}</h2>${p.concerns.length>1?`<p>${L('Also on your mind','同时关注','Juga difikirkan')}: ${list(p.concerns.filter(c=>c!==p.primary))}</p>`:''}${evidence(a,['Q02','Q08'])}</div><div><h3>${L('What you want to achieve','你希望实现的目标','Matlamat yang ingin dicapai')}</h3><p>${p.goals.length?list(p.goals):e(P(p.preference))}</p></div></section><section class="personal-association"><div><span class="an-eyebrow">${L('INTEREST → TASK → DIRECTION','兴趣 → 任务 → 方向','MINAT → TUGAS → ARAH')}</span><h2>${L('Where your interests meet the work.','让兴趣与真实工作相遇。','Apabila minat bertemu tugas sebenar.')}</h2><p class="personal-interest">${p.interests.length?list(p.interests):e(P(p.directionLabel))}</p><p>${e(P(p.preference))}</p>${evidence(a,['Q12',a.direction+'01',a.direction+'02',a.direction+'03',a.direction+'04'])}</div><div class="personal-role"><span>${L('A direction to explore first','优先探索的方向','Arah awal untuk diterokai')}</span><h3>${e(P(r.title))}</h3><p>${e(P(r.project))}</p>${button(L('Explore the career galaxy','进入职业星图','Terokai galaksi kerjaya'),'page:galaxy')}</div></section><section class="personal-context"><div><span class="an-eyebrow">${L('EXPERIENCE YOU CAN BUILD ON','可以继续发展的经历','PENGALAMAN UNTUK DIKEMBANGKAN')}</span><h2>${e(P(p.phaseLabel))}</h2><p>${p.experience.length?list(p.experience):e(P(p.preference))}</p>${p.background.length?`<p>${L('Your fields','已有领域','Bidang anda')}: ${list(p.background)}</p>`:''}${evidence(a,['Q04','Q05','Q06',a.direction+'05',a.direction+'06'])}</div><div><span class="an-eyebrow">${L('WHAT TO WORK THROUGH','重点突破','HALANGAN UNTUK DIATASI')}</span><h2>${p.barriers.length?list(p.barriers):L('Choose one focused next step','选择一个聚焦的下一步','Pilih satu langkah fokus')}</h2><p>${e(P(p.next.why))}</p>${evidence(a,['Q07'])}</div></section>${p.markets.length?`<section class="personal-markets"><h3>${L('Your market perspectives','你的市场视角','Perspektif pasaran anda')}</h3><p>${list(p.markets)}</p><strong>${L('Primary reference','主要参考','Rujukan utama')}: ${e(P(p.primaryMarket))}</strong>${evidence(a,['Q09'])}</section>`:''}${a.relatedDirections.length?`<details class="personal-related"><summary>${L('Explore the other interests you selected','探索你同时选择的其他兴趣','Terokai minat lain yang dipilih')}</summary><p>${L('These are occupational references for every selected direction, without a suitability ranking.','以下覆盖你已选择的其他方向，是职业参考，不是适合度排序。','Ini rujukan pekerjaan bagi setiap arah dipilih, tanpa ranking kesesuaian.')}</p><ul>${a.relatedDirections.map(r=>`<li><strong>${e(P(r.title))}</strong> <a target="_blank" rel="noopener noreferrer" href="${e(r.source.url)}">O*NET ↗</a><p lang="en">${e(r.source.tasks[0]?.label||r.source.description)}</p></li>`).join('')}</ul></details>`:''}<section class="personal-next"><span class="an-eyebrow">${L('YOUR NEXT MOVE','你的下一步','LANGKAH SETERUSNYA')}</span><h2>${e(P(p.next.title))}</h2><p>${e(P(p.next.why))}</p><strong>${e(P(p.next.task))}</strong>${evidence(a,p.next.evidenceIds)}${button(L('Plan this in What If','在 What If 中规划','Rancang dalam What If'),'plan:'+r.id)}</section>${methodology(a)}</div>`;
}
export function renderAI(a,options,{evidence,methodology,button,aiPanel}){
 const x=a.aiEvidence,active=a.ai.find(d=>d.id===options.aiFocus)||a.ai.find(d=>d.mode==='explore')||a.ai[0],role=a.roles[0];
 const basis={reported:L('Your selected practices','你明确选择的实践','Amalan yang anda pilih'),inferred:L('Habits suggested by your answers','问卷体现的习惯','Amalan dicadangkan oleh jawapan'),explore:L('A useful next skill to try','下一项值得尝试的技能','Kemahiran seterusnya untuk dicuba')};
 return `<div class="an-view an-capability" data-rebuild="capability"><header class="an-head"><span class="an-eyebrow">02 / 05 · ${L('YOUR AI PRACTICE','你的 AI 实践','AMALAN AI ANDA')}</span><h1 tabindex="-1">${e(P(x.headline))}</h1><p>${e(P(x.contrast.copy))}</p></header><section class="ai-reported"><h2>${L('How you use AI today','你目前如何使用 AI','Cara anda menggunakan AI hari ini')}</h2>${x.modes.length?`<ul>${x.modes.map(m=>`<li>${e(P(m.label))}</li>`).join('')}</ul>`:`<p>${L('Use the first experiment below to discover where AI can help with a task you care about.','从下方的第一项实验开始，寻找 AI 能在哪个你关心的任务中发挥作用。','Gunakan eksperimen pertama di bawah untuk mencari bantuan AI bagi tugas bermakna.')}</p>`}${evidence(a,['Q13','G03',a.direction+'07'])}</section><section class="ai-workbench"><div class="ai-workbench-title"><span class="an-eyebrow">${L('YOUR EVIDENCE, CONNECTED','把你的回答连接起来','BUKTI ANDA, DIHUBUNGKAN')}</span><p>${L('Select a dimension to explore its evidence, occupational connection and next task. Lines show evidence relationships, not proficiency scores.','选择一个维度查看回答依据、职业关联和下一步任务。连线展示证据关系，不表示能力评分。','Pilih dimensi untuk bukti, kaitan pekerjaan dan tugas seterusnya. Garis ialah hubungan bukti, bukan skor kemahiran.')}</p></div><div class="ai-structure"><nav aria-label="${L('AI practice dimensions','AI 实践维度','Dimensi amalan AI')}">${a.ai.map((d,i)=>`<button type="button" data-combined-action="ai-focus:${d.id}" class="ai-node ${d.mode} ${active.id===d.id?'active':''}" aria-pressed="${active.id===d.id}"><span>0${i+1}</span><strong>${e(P(titles[d.id]))}</strong><small>${basis[d.mode]}</small></button>`).join('')}</nav><div class="ai-connection" aria-hidden="true"><svg viewBox="0 0 100 400" preserveAspectRatio="none">${[40,120,200,280,360].map(y=>`<path d="M0 ${y} Q50 ${y} 100 200"/>`).join('')}</svg></div><article class="ai-inspector" aria-live="polite"><span class="an-eyebrow">${basis[active.mode]}</span><h2>${e(P(titles[active.id]))}</h2><p>${e(P(active.task))}</p>${evidence(a,active.evidenceIds)}<div class="ai-role-requirements"><span>${L('Connected to this occupational requirement','连接到职业要求','Dikaitkan dengan keperluan pekerjaan')}</span><h3>${e(P(role.title))}</h3><ul>${active.requirements.map(r=>`<li lang="en">${e(r.label)}</li>`).join('')}</ul><a href="${e(role.source.url)}" target="_blank" rel="noopener noreferrer">O*NET ↗</a></div>${button(L('Plan this practice','规划这项实践','Rancang latihan ini'),'plan:'+role.id)}</article></div></section><section class="ai-next"><div><span class="an-eyebrow">${L('MAKE THE NEXT STEP COUNT','让下一步真正有用','JADIKAN LANGKAH SETERUSNYA BERMAKNA')}</span><h2>${e(P(a.personal.next.title))}</h2><p>${e(P(a.personal.next.why))}</p></div><div><p>${e(P(a.personal.next.task))}</p>${evidence(a,a.personal.next.evidenceIds)}${button(L('Compare a learning plan','比较学习计划','Bandingkan pelan pembelajaran'),'plan:'+role.id)}</div></section>${aiPanel(options)}${methodology(a)}</div>`;
}
export function renderPlanning(a,options,{header,methodology,button}){
 const s=simulate(a,options.assumptions),r=a.roles.find(r=>r.id===s.roleId);
 const select=(key,title,values,selected)=>`<label>${title}<select data-v2-control="${key}">${values.map(([v,t])=>`<option value="${e(v)}" ${String(v)===String(selected)?'selected':''}>${e(t)}</option>`).join('')}</select></label>`;
 let previous=new Set();
 const horizons=s.horizons.map((h,i)=>{const newStages=s.stages.filter(stage=>h.planned.includes(stage.id)&&!previous.has(stage.id));previous=new Set(h.planned);const underway=s.stages.find(stage=>stage.startHours<h.budgetHours&&stage.endHours>h.budgetHours);return `<details class="plan-horizon" ${i===0?'open':''}><summary><strong>${[L('2 months','2 个月','2 bulan'),L('1 year','1 年','1 tahun'),L('2 years','2 年','2 tahun')][i]}</strong><span>${h.budgetHours} ${L('hours of available time','小时可投入预算','jam masa tersedia')}</span></summary><div>${newStages.length?newStages.map(stage=>`<article><h3>${e(P(stage.title))}</h3><p>${e(P(stage.task))}</p><dl><div><dt>${L('Estimated effort','预计投入','Anggaran usaha')}</dt><dd>${stage.hours} h</dd></div><div><dt>${L('Prerequisite','先修条件','Prasyarat')}</dt><dd>${stage.dependencies.length?stage.dependencies.map(id=>e(P(s.stages.find(st=>st.id===id).title))).join(' → '):L('Start here','从这里开始','Mula di sini')}</dd></div></dl><p>${L('Review criterion','阶段验收','Kriteria semakan')}: ${e(P(stage.check))}</p></article>`).join(''):`<article><h3>${h.budgetHours===0?L('Choose a sustainable time budget','先设定可持续的时间预算','Pilih bajet masa mampan'):underway?e(P(underway.title)):L('Review your first case, then choose the next one','复盘第一个案例，再决定下一项实践','Semak kes pertama, kemudian pilih seterusnya')}</h3><p>${underway?e(P(underway.task)):e(P(r.project))}</p><p>${L('Use feedback on the first exercise to decide the next project scope. Extra available hours are not automatic skill growth.','用第一次练习的反馈决定下一个项目范围。更多可投入时间不代表技能自动增长。','Gunakan maklum balas latihan pertama untuk skop seterusnya. Masa tambahan bukan pertumbuhan kemahiran automatik.')}</p></article>`}${underway&&newStages.length?`<p>${L('The next stage can begin within this budget','该预算内可开始下一阶段','Peringkat seterusnya boleh bermula')}: ${e(P(underway.title))}</p>`:''}<p class="plan-role-link">${L('Career connection','与职业目标的关系','Kaitan kerjaya')}: ${e(P(r.title))} → <span lang="en">${e(s.selectedRequirement?.label||r.requirements[0]?.label||P(r.project))}</span></p></div></details>`;}).join('');
 return `<div class="an-view an-whatif" data-rebuild="whatif">${header(4,L('A PLAN YOU CAN TEST','可以实践检验的计划','PELAN UNTUK DIUJI'),L('Shape a pathway<br>around your real life.','围绕现实条件，<br>规划发展路径。','Bentuk laluan mengikut<br>kehidupan sebenar anda.'),e(P(r.title))+' · '+e(P(a.personal.next.why)))}<section class="an-controls">${select('targetCareer',L('Target career','目标职业','Kerjaya sasaran'),a.roles.map(r=>[r.id,P(r.title)]),s.roleId)}${select('focusSkill',L('Practice priority','练习重点','Keutamaan latihan'),[['foundations',L('Prerequisites','先修基础','Prasyarat')],['practice',L('Task sample','任务实践','Latihan tugas')],['verification',L('Quality checking','质量核验','Semakan kualiti')],['portfolio',L('Portfolio case','作品案例','Kes portfolio')],...r.requirements.map(x=>[x.id,x.label])],s.focusSelection)}<label>${L('Hours per week','每周可投入小时','Jam seminggu')}<input type="number" data-v2-control="planHours" min="0" max="40" step="0.5" value="${s.weeklyHours}"></label>${select('skillEvidence',L('Starting assumption','起点假设','Andaian permulaan'),[['baseline',L('Keep my questionnaire starting point','保持问卷中的起点','Kekalkan titik permulaan soal selidik')],['practiced',L('Assume this task has already been practised and reviewed','假设这项任务已经练习并复核','Andaikan tugas sudah dilatih dan disemak')]],s.assumedEvidence?'practiced':'baseline')}</section><p class="plan-budget-note">${s.budgetAssumed?L('The initial five-hour budget is adjustable.','初始五小时预算可自行调整。','Bajet awal lima jam boleh diubah.'):L('This time budget applies to the scenario.','时间预算仅用于本情景。','Bajet masa ini untuk senario ini.')} ${L('Time schedules practice; progress depends on what you produce and check.','时间用于安排实践，实际进展取决于完成的成果与核验。','Masa menjadual latihan; kemajuan bergantung pada hasil serta semakan.')}</p>${scenarioChart(a,s)}<section class="plan-path"><h2>${L('Your practice pathway','你的实践路径','Laluan latihan anda')}</h2><ol class="an-timeline">${s.stages.map(stage=>`<li><span class="an-step-dot"></span><div><small>${stage.hours} h · ${stage.endWeek===null?L('Schedule after choosing a time budget','设定预算后安排','Jadual selepas memilih bajet'):L('Planned review: week','计划复核：第几周','Semakan dirancang: minggu')+' '+stage.endWeek}</small><h3>${e(P(stage.title))}</h3><p>${e(P(stage.task))}</p><p class="an-check">${e(P(stage.check))}</p></div></li>`).join('')}</ol></section><section class="plan-horizons"><h2>${L('What fits into each horizon?','不同时间跨度可以开展什么？','Apakah yang muat dalam setiap tempoh?')}</h2>${horizons}</section><div class="plan-reset">${button(L('Restore my starting assumptions','恢复起点假设','Pulihkan andaian permulaan'),'v2-reset')}</div>${methodology(a)}</div>`;
}
